import subprocess, os, signal, time, sys, glob

env = dict(os.environ)
env["HOME"]="/tmp/probe_1073"; env["XDG_CONFIG_HOME"]="/tmp/probe_1073/.config"
env["PIER_CONFIG_PATH"]="/tmp/probe_1073/t2.toml"

def masks(pid):
    try:
        with open(f"/proc/{pid}/status") as f:
            return [l.strip() for l in f if l.startswith(("SigIgn","SigCgt","SigBlk"))]
    except FileNotFoundError:
        return ["<dead>"]

mode = sys.argv[1]
p = subprocess.Popen(["/workspace/executable","run","sleeper"],
                     stdout=open(f"py_{mode}.out","w"), stderr=open(f"py_{mode}.err","w"),
                     start_new_session=True, env=env)
time.sleep(1)
children = glob.glob(f"/proc/[0-9]*/stat")
# find child chain
def kids(pid):
    r=[]
    for s in glob.glob("/proc/[0-9]*/stat"):
        try:
            parts=open(s).read().rsplit(')',1)[1].split()
            if int(parts[1])==pid: r.append(int(s.split('/')[2]))
        except Exception: pass
    return r
print("pier pid", p.pid, "masks:", masks(p.pid))
chain=[]
cur=[p.pid]
while cur:
    nxt=[]
    for c in cur:
        for k in kids(c):
            nxt.append(k); chain.append(k)
    cur=nxt
for c in chain:
    cmd = open(f"/proc/{c}/cmdline").read().replace('\0',' ') if os.path.exists(f"/proc/{c}/cmdline") else "?"
    print(f"child {c}: {cmd!r} masks: {masks(c)}")

if mode=="int_pier":
    os.kill(p.pid, signal.SIGINT)
elif mode=="term_pier":
    os.kill(p.pid, signal.SIGTERM)
elif mode=="int_group":
    os.killpg(p.pid, signal.SIGINT)
time.sleep(2)
print("after signal: pier poll =", p.poll())
for c in chain:
    print(f"child {c} alive={os.path.exists(f'/proc/{c}')}")
if p.poll() is None:
    rc = p.wait()
    print("pier waited, exit =", rc)
else:
    print("pier exit =", p.returncode)
